let regex = /^john@gmail\.com$/;
regex.test('e-mail: john@gmail.com'); // false
regex.test('john@gmail.com');        // true

let regex = /^(\w+)@(\w+(\.\w{2,3})+)$/;
let resultado = regex.exec('john@gmail.com.br');

console.log(resultado[0]); // 'john@gmail.com.br' (Match total)
console.log(resultado[1]); // 'john' (Usuário)
console.log(resultado[2]); // 'gmail.com.br' (Domínio completo)
console.log(resultado[3]); // '.br' (Última extensão)

playgroundCode:
// ============================================================================
// Aula 11: Expressões Regulares (RegExp) - Rodrigo Branas
// ============================================================================

console.info('1. CRIAÇÃO E VERIFICAÇÃO DE TIPO');
const regexLiteral = /john@gmail\.com/;
const regexConstrutor = new RegExp('john@gmail\\.com');

console.log('typeof /.../:', typeof regexLiteral);       // 'object'
console.log('teste literal:', regexLiteral.test('john@gmail.com')); // true
console.log('teste construtor:', regexConstrutor.test('john@gmail.com')); // true

console.info('\n2. MÉTODOS NATIVOS: exec(), match(), replace(), split()');
const emailExemplo = 'john@gmail.com';
const resultadoExec = regexLiteral.exec(emailExemplo);
console.log('resultado exec():', resultadoExec[0]);

const substituicao = emailExemplo.replace(/john/, 'jane');
console.log('replace("john" -> "jane"):', substituicao);

const palavras = 'JavaScript,TypeScript;NodeJS'.split(/[,;]\s*/);
console.log('split com regex:', palavras);

console.info('\n3. EVOLUÇÃO DO REGEX DE E-MAIL (ESTUDO DE CASO)');
// Validando nome de usuário alfanumérico e domínio com 2 a 3 caracteres
const regexEmailFlexivel = /^\w+@\w+(\.\w{2,3})+$/;

console.log('john@gmail.com:', regexEmailFlexivel.test('john@gmail.com'));       // true
console.log('john@gmail.com.br:', regexEmailFlexivel.test('john@gmail.com.br')); // true
console.log('email inválido:', regexEmailFlexivel.test('invalido@@gmail'));     // false

console.info('\n4. EXTRAÇÃO DE GRUPOS DE CAPTURA COM exec()');
const regexComGrupos = /^(\w+)@(\w+(\.\w{2,3})+)$/;
const matchCompleto = regexComGrupos.exec('john@gmail.com.br');

if (matchCompleto) {
  console.log('Match Completo (resultado[0]):', matchCompleto[0]);
  console.log('Nome de Usuário (resultado[1]):', matchCompleto[1]);
  console.log('Domínio Total   (resultado[2]):', matchCompleto[2]);
  console.log('Última Extensão (resultado[3]):', matchCompleto[3]);
}
